import crypto from 'crypto';
import{runpod}from'./_runpod';

const EXPECTED_TOKEN_HASH='7c6694f352451253ea78437093b3c18d286a9e9e990d1b1fa5ea0afe7e9880e4';
const TEMPLATE_ID='2w5x8empgg';
const ENDPOINT_ID='id81aby9nfth9h';
const SOURCE_COMMIT='a5f0d64498d278e3e364473abb6e15871f55bfeb';
const BUNDLE_SHA256='76775ff5ac85dca71f1fe243c1e8f04ea8e9bdf46d0262d454303b0d6667dfc6';
const BUNDLE_B64="";

function authorized(req){
  const supplied=String(req.headers['x-mcs-admin-token']||req.query?.token||'');
  const actual=crypto.createHash('sha256').update(supplied).digest('hex');
  try{
    const left=Buffer.from(actual,'hex');
    const right=Buffer.from(EXPECTED_TOKEN_HASH,'hex');
    return left.length===right.length&&crypto.timingSafeEqual(left,right);
  }catch{return false}
}

function templateBody(template,cmd){
  const body={
    containerDiskInGb:template.containerDiskInGb,
    containerRegistryAuthId:template.containerRegistryAuthId||undefined,
    dockerEntrypoint:['/bin/bash','-lc'],
    dockerStartCmd:[cmd],
    env:template.env||{},
    imageName:template.imageName,
    isPublic:!!template.isPublic,
    name:template.name,
    ports:template.ports||[],
    readme:template.readme||'',
    volumeInGb:template.volumeInGb||0,
    volumeMountPath:template.volumeMountPath||'/workspace'
  };
  Object.keys(body).forEach(name=>body[name]===undefined&&delete body[name]);
  return body;
}

export default async function handler(req,res){
  res.setHeader('Cache-Control','private, no-store');
  res.setHeader('Referrer-Policy','no-referrer');
  if(req.method!=='GET')return res.status(405).json({error:'GET only'});
  if(!authorized(req))return res.status(401).json({error:'Unauthorized'});
  const action=String(req.query?.action||'status');
  const{key}=runpod();
  if(!key)return res.status(503).json({error:'RunPod key missing'});
  const headers={Authorization:`Bearer ${key}`,'Content-Type':'application/json'};

  try{
    if(action==='patch'){
      const lookup=await fetch(`https://rest.runpod.io/v1/templates/${TEMPLATE_ID}`,{headers});
      const template=await lookup.json();
      if(!lookup.ok)return res.status(lookup.status).json({error:'Template lookup failed'});
      const command=`set -euo pipefail; mkdir -p /opt/mcs-bundle; python -c "import base64; open('/tmp/mcs-worker.tar.gz','wb').write(base64.b64decode('${BUNDLE_B64}'))"; tar -xzf /tmp/mcs-worker.tar.gz -C /opt/mcs-bundle; export PYTHONPATH="/opt/mcs-bundle:\${PYTHONPATH:-}"; echo "MCS source commit: ${SOURCE_COMMIT}"; echo "MCS bundle sha256: ${BUNDLE_SHA256}"; exec bash /opt/mcs-bundle/start.sh`;
      const patch=await fetch(`https://rest.runpod.io/v1/templates/${TEMPLATE_ID}`,{method:'PATCH',headers,body:JSON.stringify(templateBody(template,command))});
      if(!patch.ok)return res.status(patch.status).json({error:'Template bundle patch failed'});
      const down=await fetch(`https://rest.runpod.io/v1/endpoints/${ENDPOINT_ID}`,{method:'PATCH',headers,body:JSON.stringify({workersMin:0,workersMax:0})});
      if(!down.ok)return res.status(down.status).json({error:'Worker scale-down failed'});
      return res.status(200).json({ok:true,phase:'scaled_down',sourceCommit:SOURCE_COMMIT,bundleSha256:BUNDLE_SHA256});
    }

    const lookup=await fetch(`https://rest.runpod.io/v1/endpoints/${ENDPOINT_ID}?includeWorkers=true`,{headers});
    const endpoint=await lookup.json();
    if(!lookup.ok)return res.status(lookup.status).json({error:'Endpoint lookup failed'});
    const workers=(endpoint.workers||[]).map(worker=>({id:worker.id,status:worker.status,desiredStatus:worker.desiredStatus,slsVersion:worker.slsVersion}));
    const active=workers.filter(worker=>worker.status==='RUNNING'||worker.desiredStatus==='RUNNING');

    if(action==='up'){
      if(active.length)return res.status(409).json({error:'Old workers are still stopping',workers});
      const up=await fetch(`https://rest.runpod.io/v1/endpoints/${ENDPOINT_ID}`,{method:'PATCH',headers,body:JSON.stringify({workersMin:0,workersMax:4})});
      const updated=await up.json().catch(()=>({}));
      if(!up.ok)return res.status(up.status).json({error:'Worker scale-up failed'});
      return res.status(200).json({ok:true,phase:'scaled_up',endpointVersion:updated.version??null,sourceCommit:SOURCE_COMMIT,bundleSha256:BUNDLE_SHA256});
    }

    return res.status(200).json({ok:true,phase:'status',endpointVersion:endpoint.version,workersMin:endpoint.workersMin,workersMax:endpoint.workersMax,workers});
  }catch(error){return res.status(502).json({error:error.message})}
}

